const e={problemsTitle:"Problems it solves",approachTitle:"How we do it",casesTitle:"Example applications",faqTitle:"Frequently asked questions",otherTitle:"Other NDXai services",cta:"Talk to the team",updated:"Last updated",identityTitle:"Site owner",identity:{legalName:"Owner",taxId:"Tax ID (NIF)",registry:"Companies register",address:"Registered address",email:"Email",phone:"Phone"}},t=JSON.parse(`{"predictive":{"seoTitle":"AI predictive maintenance for manufacturing | NDXai","seoDescription":"Anticipate breakdowns with AI models trained on your own machine data. Custom predictive maintenance for industrial plants, from Vic (Barcelona).","h1":"AI predictive maintenance for manufacturing","problems":["Unplanned stoppages that halt the line and delay orders.","Calendar-based preventive maintenance that replaces parts that were still fine.","Recurring failures with no known root cause.","Sensor, PLC or SCADA data that is collected but never used."],"approach":["We review which assets are critical and what data exists: vibration, temperature, power draw, failure history and work orders.","If data is missing, we propose which sensors or records to add before training anything.","We train anomaly detection and failure prediction models on your plant's data.","We deliver alerts where the maintenance team already works: a dashboard, email or your maintenance management system (CMMS).","We review the alerts with the team and retune the model after each intervention."],"cases":["Motors, pumps and compressors: detecting bearing wear from vibration and temperature.","Packaging lines: a warning when a machine starts to drift, before it produces rejects.","Industrial refrigeration and HVAC: power and temperature anomalies.","Fleets of similar machines: comparing units to find the one behaving differently."],"faq":[{"q":"What data do you need for predictive maintenance?","a":"Ideally, sensor signals (vibration, temperature, power, pressure) and a history of failures or interventions. If only part of that exists, we can start with anomaly detection and add data over time."},{"q":"Do we need to install new sensors?","a":"It depends on the machine. Many already produce data in the PLC or SCADA that is not being stored. During the assessment we see what can be reused and what would need adding."},{"q":"What is the difference between preventive and predictive maintenance?","a":"Preventive maintenance acts on a calendar or on running hours, whether the part needs it or not. Predictive maintenance acts when the data shows a failure is approaching."}]},"vision":{"seoTitle":"Computer vision for quality control | NDXai","seoDescription":"Automated inspection with computer vision and neural networks: defect detection, counting and traceability on production lines. AI consultancy in Vic.","h1":"Computer vision for industrial quality control","problems":["Manual visual inspection that is slow and varies by person and shift.","Defects reaching the customer because only a sample is checked.","High reject rates with no data on when and where the defect occurs.","Classic vision systems that fail when the product or lighting changes."],"approach":["We define with the quality team what counts as a defect and which cases are borderline.","We collect and label images of good and defective parts on the line itself.","We train classification, detection or segmentation neural networks, depending on the case.","We deploy the model at the line, with suitable camera and lighting, and connect it to the reject mechanism or the plant system.","We store images and results for traceability and to retrain the model when the product changes."],"cases":["Food: product appearance, shape and colour, pack sealing and labelling.","Pharma: presence and integrity checks on blisters, vials and packs.","Metal and plastics: scratches, pores, burrs and surface defects.","Logistics: code and label reading, counting and parcel verification."],"faq":[{"q":"How many images are needed to train a model?","a":"It depends on how much the product and the defect vary. You can often start with a small set of well-labelled images and grow it with what is collected in production."},{"q":"Does it keep up with line speed?","a":"The system is sized for the line's throughput. During the assessment we validate camera, lighting and response time before deploying anything."},{"q":"Can we reuse the cameras we already have?","a":"Yes, if resolution and lighting are good enough. If not, we propose the smallest change needed."}]},"digital":{"seoTitle":"Digital twins for industrial plants | NDXai","seoDescription":"Digital twins to simulate process, capacity and layout changes without stopping production. Custom models built on your plant's own data.","h1":"Digital twins to simulate and improve your plant","problems":["Process changes that can only be tested by stopping the line.","Machinery investments decided without knowing where the bottleneck is.","Production planning done with spreadsheets and gut feeling.","Difficulty predicting the effect of a change in product, shift pattern or demand."],"approach":["We narrow down the question to answer: capacity, bottlenecks, energy use or quality.","We model the process with its real data: cycle times, stoppages, changeovers and material flows.","We validate the twin against the plant's actual behaviour.","We simulate scenarios with your team and measure their effect before anything is changed.","Where it makes sense, we connect the twin to live data so it tracks what is happening in the plant."],"cases":["Testing a new machine layout or a change in workflow.","Sizing a line or warehouse extension.","Estimating the impact of a shift change or a demand peak.","Finding the configuration that cuts energy use without losing output."],"faq":[{"q":"What is a digital twin?","a":"It is a virtual model of a machine, line or plant that behaves like the real one because it is fed with its data. It is used to test changes and predict outcomes without stopping production."},{"q":"Does the plant need to be fully instrumented?","a":"Not to get started. A first twin can be built from historical production data, with live data added later."},{"q":"How long does it take to build a digital twin?","a":"It depends on the scope. We recommend starting with one line or process and extending it once it is delivering results."}]},"bots":{"seoTitle":"AI agents and bots for business | NDXai","seoDescription":"Custom AI agents and bots: customer service, internal document search and task automation, connected to your own systems and data.","h1":"Custom AI agents and bots for business","problems":["Repetitive customer queries that tie up the team.","Internal information scattered across documents, emails and systems that are hard to search.","Admin tasks that involve copying data from one system to another.","Out-of-hours or multilingual support the team cannot cover."],"approach":["We define what the agent should do, with which sources, and how far it can go without a person stepping in.","We connect it to your documentation and systems (ERP, CRM, databases) so it answers with your own information, not generic content.","We set limits: what it can read, which actions it can take and when it must hand over to a person.","We test it with real cases from your team before opening it to customers.","We review conversations to improve the answers and extend what it can do."],"cases":["A customer service bot on your website for questions about orders, lead times or invoicing.","An internal agent that finds procedures, datasheets or documents in seconds.","An agent that reads emails or orders, extracts the data and enters it into your system.","An agent for maintenance technicians with access to manuals and the incident history."],"faq":[{"q":"What is the difference between a bot and an AI agent?","a":"A bot answers questions. An agent can also take actions: query a system, fill in a form or open a ticket, within the limits it is given."},{"q":"Is our data protected?","a":"The agent only accesses the sources it is authorised to use and is designed with security in mind from the start. The proposal sets out where the data is processed."},{"q":"Can it be integrated into our website or tools?","a":"Yes. It can be embedded in a website, an app or internal tools, and connected to existing systems through their APIs."}]},"analytics":{"seoTitle":"Advanced analytics and machine learning | NDXai","seoDescription":"Demand and sales forecasting, inventory optimisation, customer segmentation and dynamic pricing with machine learning models trained on your data.","h1":"Advanced analytics and machine learning for data-driven decisions","problems":["Sales or demand forecasts made by eye or in spreadsheets.","Too much stock of some products and stockouts of others.","Data spread across ERP, CRM and spreadsheets that nobody joins up.","Reports that explain what happened but not what will happen."],"approach":["We start from a specific decision you want to improve, not from the data available.","We bring together and clean the data from the different sources.","We train forecasting, classification or optimisation models and compare them with the current method.","We deliver the result where the decision is made: a dashboard, a regular report or directly in the management system.","We track the model's accuracy over time and retrain it when the context changes."],"cases":["Demand forecasting to plan production and purchasing.","Inventory and reorder point optimisation.","Customer segmentation and churn risk detection.","Delivery route and vehicle load optimisation."],"faq":[{"q":"How is this different from a BI dashboard?","a":"BI shows what happened. Advanced analytics uses models to predict what will happen and recommend what to do."},{"q":"Is my data good enough?","a":"It is almost never perfect, and that does not stop you getting started. During the assessment we see what can be done with what exists and what is worth improving."},{"q":"Which tools do you work with?","a":"We choose the tools based on the case and the systems the client already has, and integrate the result with their ERP, CRM or database."}]},"optimization":{"seoTitle":"Intelligent process automation with AI | NDXai","seoDescription":"Automate invoices, orders and admin tasks with AI: document data extraction, classification and integration with your ERP.","h1":"Intelligent process automation with AI","problems":["Hours spent keying in data from invoices, delivery notes or orders.","Transcription errors that are caught late.","Processes that depend on the one person who knows how they are done.","Long response times because work piles up in queues."],"approach":["We map the process with the people who run it every day and pick the steps worth automating.","We use AI to read documents and emails, extract the data and classify them.","We connect the output to the ERP or management system so nothing has to be typed twice.","We keep a person in the loop to validate borderline cases.","We measure time and errors before and after to confirm the improvement."],"cases":["Supplier invoice handling: reading, validation and posting.","Entry of orders received by email or as PDFs.","Classification and routing of emails and requests.","Regular reports generated from several sources."],"faq":[{"q":"How is it different from traditional RPA?","a":"RPA repeats clicks on fixed screens and breaks when the format changes. AI understands variable documents and text, so it covers cases RPA cannot."},{"q":"Does it replace people on the team?","a":"The aim is to take repetitive work off them so they can focus on higher-value tasks. Borderline cases are still validated by a person."},{"q":"Where do we start?","a":"With one well-defined process that has volume and clear rules. Once it works, it is extended to others."}]}}`),a={privacy:{title:"Privacy policy",seoDescription:"How NDXai (Neural Dynamics AI S.L.) handles the personal data of website visitors: contact, chat, analytics, cookies and your rights.",updated:"2026-10-01",intro:"This policy explains which personal data Neural Dynamics AI S.L. (NDXai) processes when you visit www.ndxai.eu or get in touch with us, for what purpose, and what rights you have. The data controller is the site owner.",sections:[{title:"What data we process and why",body:["Contact. If you email us, call us or contact us on LinkedIn, we process the data you give us (name, company, email, phone and the content of your message) to reply and, where relevant, prepare a proposal.","Website chat. Messages you type to the website assistant are sent to our server and to a language model provider to generate the reply. Do not enter personal data or confidential information.","Analytics. We use Google Analytics to understand, in aggregate, how the site is used (pages visited, device type, approximate location). This service uses cookies.","Language preference. If you switch language, we store your choice in your browser (local storage) to remember it. This data does not leave your device."]},{title:"Legal basis",body:["We process contact and chat data to deal with your enquiry: taking steps at your request prior to entering into a contract (Art. 6(1)(b) GDPR) and our legitimate interest in answering professional enquiries (Art. 6(1)(f) GDPR)."]},{title:"Cookies",body:["The only cookies on the site are those set by Google Analytics (_ga and _ga_<identifier>), which distinguish visitors and sessions and expire after two years at most.","You can block or delete them in your browser settings, or install the Google Analytics opt-out add-on."]},{title:"Who we share data with",body:["We do not sell or pass data to third parties. The providers that run the site are involved: GitHub (website hosting), Google (analytics and fonts) and Render (hosting of the chat server). Some of these providers are located in the United States."]},{title:"How long we keep it",body:["Contact data is kept for as long as the relationship lasts and, afterwards, for the time needed to meet possible legal liabilities. Analytics data is kept for the retention period configured in Google Analytics."]},{title:"Your rights",body:["You can exercise your rights of access, rectification, erasure, objection, restriction and portability by writing to the email address shown in the site owner details.","If you believe we have not handled your request properly, you can lodge a complaint with the Spanish Data Protection Agency (www.aepd.es)."]},{title:"Changes to this policy",body:["If we change how we handle data, we will update this page and the last-updated date."]}]},notice:{title:"Legal notice",seoDescription:"Legal notice for www.ndxai.eu: site owner, terms of use, virtual assistant, intellectual property and liability.",updated:"2026-10-01",intro:"In compliance with Spanish Law 34/2002 on information society services and electronic commerce (LSSI-CE), this notice sets out the details of the owner of this website and its terms of use.",sections:[{title:"Purpose",body:["This website presents NDXai's artificial intelligence consultancy and development services. The information it contains is general in nature and is not a contractual offer; the terms of each project are set out in the corresponding proposal."]},{title:"Terms of use",body:["Access to the site is free and open. Visitors agree to use it lawfully and not to do anything that could damage it or prevent it from working."]},{title:"Virtual assistant",body:["The website chat is an automated assistant based on artificial intelligence. Its answers are for guidance only, may contain errors, and neither replace advice from the team nor constitute any contractual commitment."]},{title:"Intellectual and industrial property",body:["The text, design, logos and code of this website belong to Neural Dynamics AI S.L. or are used under licence. They may not be reproduced or distributed for commercial purposes without permission. Third-party trademarks and linked content belong to their owners."]},{title:"Third-party links",body:["The site may link to third-party pages. NDXai is not responsible for their content or their privacy policies."]},{title:"Liability",body:["NDXai endeavours to keep the information on the site correct and up to date, but does not guarantee that it is free of errors or that the site will be available without interruption."]},{title:"Governing law",body:["This legal notice is governed by Spanish law. Any dispute will be heard by the courts that have jurisdiction under the applicable rules."]}]}},i={ui:e,services:t,legal:a};export{i as default,a as legal,t as services,e as ui};
